const KEY = "DEMO_KEY";

async function getAsteroids() {
  const day = new Date().toISOString().slice(0, 10);
  const url = `https://api.nasa.gov/neo/rest/v1/feed?start_date=${day}&end_date=${day}&api_key=${KEY}`;
  const reply = await fetch(url);
  if (!reply.ok) throw new Error(`NASA replied ${reply.status}`);
  const data = await reply.json();

  // One list per date. We asked for one date.
  return (data.near_earth_objects[day] ?? []).map((rock) => {
    const m = rock.estimated_diameter.meters;
    const pass = rock.close_approach_data[0];
    return {
      name: rock.name.replace(/[()]/g, ""),
      metres: (m.estimated_diameter_min + m.estimated_diameter_max) / 2,
      hazardous: rock.is_potentially_hazardous_asteroid,
      moonDistances: Number(pass.miss_distance.lunar), // sent as text
      kmPerSecond: Number(pass.relative_velocity.kilometers_per_second),
    };
  });
}

const landmarks = [
  { name: "a cricket pitch", metres: 20 },
  { name: "the Qutub Minar", metres: 73 },
  { name: "the Statue of Liberty", metres: 93 },
  { name: "the Eiffel Tower", metres: 330 },
  { name: "the Burj Khalifa", metres: 828 },
];

function compare(metres) {
  // Pick the landmark whose size is closest to the asteroid's size.
  const closest = landmarks.reduce((best, landmark) =>
    Math.abs(landmark.metres - metres) < Math.abs(best.metres - metres) ? landmark : best,
  );
  const times = metres / closest.metres;
  return `${times.toFixed(1)} times the height of ${closest.name}`;
}

console.log(compare(49)); // 0.7 times the height of the Qutub Minar

function addCard(rock) {
  const card = document.createElement("article");
  card.className = rock.hazardous ? "card hazardous" : "card";

  const title = document.createElement("h2");
  title.textContent = rock.name;

  const size = document.createElement("p");
  size.textContent = `${Math.round(rock.metres)} m wide: ${compare(rock.metres)}`;

  const where = document.createElement("p");
  where.textContent = `${rock.moonDistances.toFixed(1)} Moon distances away, at ${rock.kmPerSecond.toFixed(1)} km/s`;

  card.append(title, size, where);
  document.querySelector("#asteroids").append(card);
}

async function loadDashboard() {
  const status = document.querySelector("#status");
  try {
    const rocks = await getAsteroids();
    rocks.sort((a, b) => a.moonDistances - b.moonDistances); // closest first
    rocks.forEach(addCard);
    status.textContent = rocks.length ? `${rocks.length} asteroids today` : "No asteroids listed today.";
  } catch (error) {
    console.error(error); // the details, for you
    status.textContent = error.message.includes("429")
      ? "NASA says too many requests. Wait a while, or use your own key."
      : "Could not load asteroids. Please try again later.";
  }
}

loadDashboard();
